'use client';
import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { Activity, AlertTriangle, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Bell, Check, CheckCircle2, ChevronRight, ClipboardList, Clock3, CloudSun, Download, Leaf, MapPin, Menu, Package, Plus, QrCode, RotateCcw, Search, Settings2, ShieldCheck, Snowflake, Sprout, Thermometer, Truck, X } from 'lucide-react';
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Legend, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { seedAlerts, seedBatches, seedFacilities, seedFpos, seedShipments, seedVehicles, type Alert, type Batch, type Facility, type Fpo, type Shipment, type Vehicle } from '@/lib/freshlink-data';

type Page='Overview'|'Batches'|'Farms & FPOs'|'Cold storage'|'Refrigerated transport'|'Temperature & alerts'|'Shipments'|'Traceability'|'Analytics'|'Bookings'|'Settings';
type DemoState={batches:Batch[];fpos:Fpo[];facilities:Facility[];vehicles:Vehicle[];shipments:Shipment[];alerts:Alert[];bookings:{id:string;batch:string;facility:string;quantity:number;status:string}[];events:{title:string;detail:string;time:string}[];step:number};
const initial=():DemoState=>({batches:seedBatches(),fpos:seedFpos,facilities:seedFacilities(),vehicles:seedVehicles,shipments:seedShipments,alerts:seedAlerts,bookings:[{id:'BK-3101',batch:'FL-26001',facility:'Kolar Farmgate Pre-cooling Centre',quantity:2400,status:'Confirmed'},{id:'BK-3102',batch:'FL-26003',facility:'Nashik Valley Cold Chain',quantity:4800,status:'In service'}],events:[{title:'New produce batch registered',detail:'FL-26001 · Tomatoes · Kolar',time:'09:42 AM'},{title:'Pre-cooling completed',detail:'FL-26006 · Grapes · Nashik',time:'09:18 AM'},{title:'Storage booking confirmed',detail:'Bengaluru Agri Packhouse · 3.2 tonnes',time:'08:56 AM'},{title:'Refrigerated vehicle assigned',detail:'SHP-9001 · Kolar → Bengaluru',time:'08:31 AM'},{title:'Temperature excursion detected',detail:'FL-26008 · Review required',time:'08:12 AM'}],step:0});
function ensureUniqueBookings(bookings:DemoState['bookings']):DemoState['bookings']{
 const seen=new Set<string>();
 let highest=3100;
 for(const b of bookings){
  const num=Number(b.id?.match(/^BK-(\d+)$/)?.[1]);
  if(Number.isFinite(num))highest=Math.max(highest,num);
 }
 return bookings.map((b)=>{
  let id=b.id;
  if(!id||seen.has(id)){
   highest++;
   id=`BK-${highest}`;
  }
  seen.add(id);
  return {...b,id};
 });
}
function nextBookingId(bookings:DemoState['bookings']){
 const existing=new Set(bookings.map(b=>b.id));
 const highest=bookings.reduce((max,booking)=>{
  const number=Number(booking.id.match(/^BK-(\d+)$/)?.[1]);
  return Number.isFinite(number)?Math.max(max,number):max;
 },3100);
 let next=highest+1;
 while(existing.has(`BK-${next}`))next++;
 return `BK-${next}`;
}
const nav: {name:Page;icon:typeof Activity}[]=[{name:'Overview',icon:BarChart3},{name:'Batches',icon:Package},{name:'Farms & FPOs',icon:Sprout},{name:'Cold storage',icon:Snowflake},{name:'Refrigerated transport',icon:Truck},{name:'Temperature & alerts',icon:Thermometer},{name:'Shipments',icon:MapPin},{name:'Traceability',icon:QrCode},{name:'Analytics',icon:Activity},{name:'Bookings',icon:ClipboardList},{name:'Settings',icon:Settings2}];
const cropSpecs:{crop:string;temp:string;humidity:string}[]=[{crop:'Tomatoes',temp:'8–12°C',humidity:'85–95%'},{crop:'Mangoes',temp:'10–13°C',humidity:'85–90%'},{crop:'Grapes',temp:'0–2°C',humidity:'90–95%'},{crop:'Bananas',temp:'13–14°C',humidity:'90–95%'},{crop:'Onions',temp:'0–2°C',humidity:'65–70%'},{crop:'Potatoes',temp:'4–8°C',humidity:'90–95%'},{crop:'Leafy greens',temp:'0–5°C',humidity:'95–100%'}];
function facilitySupports(facility:Facility,crop:string){if(!facility.crops.includes(crop))return false;const facilityRange=facility.temp.match(/(\d+)[–-](\d+)/),cropRange=cropSpecs.find(spec=>spec.crop===crop)?.temp.match(/(\d+)[–-](\d+)/);return !!facilityRange&&!!cropRange&&Number(facilityRange[1])<=Number(cropRange[1])&&Number(facilityRange[2])>=Number(cropRange[2]);}
const barData=[{name:'Tomatoes',tonnes:82},{name:'Mangoes',tonnes:58},{name:'Grapes',tonnes:46},{name:'Bananas',tonnes:38},{name:'Onions',tonnes:34},{name:'Potatoes',tonnes:29}];
const lossData=[{month:'Jun',baseline:13.2,assisted:10.4},{month:'Jul',baseline:12.4,assisted:9.6},{month:'Aug',baseline:14.1,assisted:9.2},{month:'Sep',baseline:11.3,assisted:8.5},{month:'Oct',baseline:12.8,assisted:8.1},{month:'Nov',baseline:11.6,assisted:7.8}];
function number(n:number){return new Intl.NumberFormat('en-IN').format(n)}
function money(n:number){return '₹'+new Intl.NumberFormat('en-IN').format(n)}
function Badge({children}:{children:ReactNode}){const text=String(children),kind=text.toLowerCase().replaceAll(' ','-');return <span className={`fl-badge b-${kind}`}>{children}</span>}
function Button({children,onClick,kind='primary',disabled=false}:{children:ReactNode;onClick?:()=>void;kind?:'primary'|'ghost'|'soft'|'danger';disabled?:boolean}){return <button type={onClick?'button':'submit'} className={`fl-button ${kind}`} disabled={disabled} onClick={onClick}>{children}</button>}
function Title({title,subtitle,action}:{title:string;subtitle:string;action?:ReactNode}){return <div className="fl-title"><div><div className="fl-eyebrow">FRESHLINK CONTROL TOWER</div><h1>{title}</h1><p>{subtitle}</p></div>{action&&<div className="fl-title-actions">{action}</div>}</div>}
function Metric({label,value,change,icon,tone='green',foot}:{label:string;value:string;change:string;icon:ReactNode;tone?:string;foot:string}){return <article className="fl-metric"><div className="fl-metric-top"><span>{label}</span><span className={`fl-metric-icon ${tone}`}>{icon}</span></div><strong>{value}</strong><p><span><ArrowUpRight size={14}/>{change}</span>{foot}</p></article>}
function Panel({title,sub,children,action}:{title:string;sub?:string;children:ReactNode;action?:ReactNode}){return <section className="fl-panel"><div className="fl-panel-head"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div>{action}</div>{children}</section>}
function Empty({text}:{text:string}){return <div className="fl-empty"><Package size={24}/><span>{text}</span></div>}

export default function FreshLink(){
 const [data,setData]=useState<DemoState>(initial);const [loaded,setLoaded]=useState(false);const [page,setPage]=useState<Page>('Overview');const [query,setQuery]=useState('');const [cropFilter,setCropFilter]=useState('All commodities');const [statusFilter,setStatusFilter]=useState('All statuses');const [modal,setModal]=useState('');const [toast,setToast]=useState('');const [formError,setFormError]=useState('');const [selected,setSelected]=useState('FL-26001');const [bookingBatch,setBookingBatch]=useState('FL-26001');const [qr,setQr]=useState('');const [mobileOpen,setMobileOpen]=useState(false);const [sensor,setSensor]=useState(false);const [settings,setSettings]=useState({company:'FreshLink Agricultural Network',alerts:true,digest:false,crop:'All compatible crops'});
 useEffect(()=>{try{const raw=localStorage.getItem('freshlink-demo-v1');if(raw){const parsed=JSON.parse(raw) as Partial<DemoState>;const merged={...initial(),...parsed};if(merged.bookings)merged.bookings=ensureUniqueBookings(merged.bookings);setData(merged);const pref=localStorage.getItem('freshlink-prefs-v1');if(pref)setSettings(JSON.parse(pref));}const batchId=new URLSearchParams(window.location.search).get('batch');if(batchId){setSelected(batchId);setPage('Traceability')}}catch{}setLoaded(true)},[]);
 useEffect(()=>{if(loaded){localStorage.setItem('freshlink-demo-v1',JSON.stringify(data));localStorage.setItem('freshlink-prefs-v1',JSON.stringify(settings))}},[data,settings,loaded]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),3000);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(!sensor)return;const t=setInterval(()=>{setData(d=>{const batch=d.batches.find(b=>b.id===selected);if(!batch)return d;const next=Number((batch.temp+(Math.random()-.45)*.6).toFixed(1));const limits=cropSpecs.find(s=>s.crop===batch.crop)!.temp.match(/(\d+)[–-](\d+)/)!;const outside=next<Number(limits[1])||next>Number(limits[2]);const hasOpen=d.alerts.some(a=>a.batch===batch.id&&a.status!=='Resolved');const alerts=outside&&!hasOpen?[{id:`AL-${Date.now()}`,batch:batch.id,severity:Math.abs(next-Number(limits[2]))>=3?'Critical':'Warning',temp:next,location:batch.location,owner:'Unassigned',action:'Inspect produce, restore the setpoint, and record corrective action',status:'Open'},...d.alerts]:d.alerts;const events=outside&&!hasOpen?[{title:'Temperature alert triggered',detail:`${batch.id} · ${next}°C · Configured ${batch.crop} range ${cropSpecs.find(s=>s.crop===batch.crop)?.temp}`,time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})},...d.events]:d.events;if(outside&&!hasOpen)setToast(`Sensor alert: ${next}°C is outside the ${batch.crop} range.`);return{...d,batches:d.batches.map(b=>b.id===batch.id?{...b,temp:next}:b),alerts,events}})},5000);return()=>clearInterval(t)},[sensor,selected]);
 const notify=(message:string)=>setToast(message);const selectedBatch=data.batches.find(b=>b.id===selected)||data.batches[0];
 const visibleBatches=useMemo(()=>data.batches.filter(b=>`${b.id} ${b.crop} ${b.fpo} ${b.farm} ${b.variety}`.toLowerCase().includes(query.toLowerCase())&&(cropFilter==='All commodities'||b.crop===cropFilter)&&(statusFilter==='All statuses'||b.status===statusFilter)),[data.batches,query,cropFilter,statusFilter]);
 function addEvent(title:string,detail:string){setData(d=>({...d,events:[{title,detail,time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})},...d.events].slice(0,12)}))}
 function reset(){setData(initial());setSensor(false);setSelected('FL-26001');notify('FreshLink demo data has been reset.')}
 function nextDemo(){const batchId='FL-26001';if(data.step>=8){notify('Demo journey complete. Reset it to run again.');return}const step=data.step+1;let batches=data.batches.map(b=>b.id===batchId?{...b,events:[...b.events]}:b),facilities=data.facilities,vehicles=data.vehicles,shipments=data.shipments,alerts=data.alerts,bookings=data.bookings,events=data.events;const index=batches.findIndex(b=>b.id===batchId),batch=batches[index];
  const add=(title:string,detail:string)=>{batches[index]={...batches[index],events:[...batches[index].events,{title,time:new Date().toLocaleString('en-IN'),detail}]};events=[{title,detail,time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})},...events]};
  if(step===1){batches[index]={...batch,status:'Harvested',location:'Kolar, Karnataka',quantity:8000,destination:'Bengaluru, Karnataka'};add('8-tonne tomato batch confirmed','Kolar Fresh Farmers FPO · Kolar → Bengaluru')}
  if(step===2){batches[index]={...batches[index],status:'Ready for pickup'};add('Farm pickup scheduled','Kolar collection point · Today, 10:30 AM')}
  if(step===3){const facility=facilities.find(f=>facilitySupports(f,'Tomatoes')&&f.available>=8000);if(!facility){notify('No compatible facility has 8,000 kg capacity. Reset demo data.');return}facilities=facilities.map(f=>f.id===facility.id?{...f,available:f.available-8000}:f);batches[index]={...batches[index],facility:facility.name,status:'Booked for pre-cooling',location:facility.name};bookings=ensureUniqueBookings([{id:nextBookingId(bookings),batch:batchId,facility:facility.name,quantity:8000,status:'Confirmed'},...bookings]);add('Compatible packhouse slot booked',`${facility.name} · 8,000 kg · Crop compatible`)}
  if(step===4){batches[index]={...batches[index],status:'Pre-cooled',temp:10};add('Grading and pre-cooling recorded','Grade A · 10°C · Temperature target 8–12°C')}
  if(step===5){const vehicle=vehicles.find(v=>v.status==='Available'&&v.capacity>=8000);if(!vehicle){notify('No available compatible-capacity reefer. Reset demo data.');return}vehicles=vehicles.map(v=>v.id===vehicle.id?{...v,status:'In Transit',destination:'Bengaluru, Karnataka'}:v);batches[index]={...batches[index],status:'In Transit',vehicle:vehicle.id,location:'NH-75 near Kolar'};shipments=[{id:'SHP-FL26001',batch:batchId,route:'Kolar → Bengaluru',vehicle:vehicle.id,status:'In Transit',eta:'2:45 PM',temp:10},...shipments];add('Refrigerated vehicle assigned',`${vehicle.id} · ${vehicle.capacity.toLocaleString('en-IN')} kg capacity · Kolar → Bengaluru`)}
  if(step===6){const alert:Alert={id:'AL-FL26001',batch:batchId,severity:'Warning',temp:14,location:'NH-75 near Kolar',owner:'Transport Desk',action:'Move cargo to 8–12°C range and inspect; record action',status:'Open'};alerts=[alert,...alerts];batches[index]={...batches[index],temp:14};add('Temperature excursion needs review','14°C is above the configured 8–12°C tomato range. Quality impact requires inspection, not assumed spoilage.')}
  if(step===7){alerts=alerts.map(a=>a.batch===batchId?{...a,status:'Resolved',action:'Reefer reset; cargo inspected by operator. Quality impact not assumed.'}:a);batches[index]={...batches[index],temp:10};add('Corrective action recorded','Reefer reset to 10°C; operator inspected cargo. Alert and original reading retained.')}
  if(step===8){batches[index]={...batches[index],status:'Delivered',location:'Bengaluru buyer handover'};shipments=shipments.map(s=>s.batch===batchId?{...s,status:'Delivered'}:s);vehicles=vehicles.map(v=>v.id===batches[index].vehicle?{...v,status:'Available',location:'Bengaluru, Karnataka'}:v);add('Buyer handover recorded','Delivered in Bengaluru · Batch passport updated')}
  setData(d=>({...d,batches,facilities,vehicles,shipments,alerts,bookings,events,step}));setSelected(batchId);notify(`Demo ${step}/8: ${['','Batch registered','Pickup scheduled','Packhouse booked','Pre-cooling recorded','Reefer assigned','Temperature alert raised','Alert resolved','Buyer delivery completed'][step]}`)
 }
 function simulateTemp(delta:number){const batch=data.batches.find(b=>b.id===selected);if(!batch)return;const spec=cropSpecs.find(s=>s.crop===batch.crop)!;const match=spec.temp.match(/(\d+)[–-](\d+)/);const next=Number((batch.temp+delta).toFixed(1));const upper=match?Number(match[2]):10;const lower=match?Number(match[1]):0;const shouldAlert=next>upper||next<lower;const exists=data.alerts.some(a=>a.batch===batch.id&&a.status!=='Resolved');setData(d=>({...d,batches:d.batches.map(b=>b.id===batch.id?{...b,temp:next}:b),alerts:shouldAlert&&!exists?[{id:`AL-${Date.now()}`,batch:batch.id,severity:Math.abs(next-upper)>=3||next<lower?'Critical':'Warning',temp:next,location:batch.location,owner:'Unassigned',action:'Inspect produce, restore setpoint and document corrective action',status:'Open'},...d.alerts]:d.alerts}));if(shouldAlert&&!exists){addEvent('Temperature alert triggered',`${batch.id} · ${next}°C · Crop-specific target: ${spec.temp}`);notify(`Temperature alert triggered: ${next}°C is outside ${batch.crop}'s ${spec.temp} target.`)}else notify(`Simulated ${delta>0?'warming':'cooling'} · ${batch.id}: ${next}°C (demo sensor)`)}
 function resolveAlert(id:string){const alert=data.alerts.find(a=>a.id===id);if(!alert)return;const note=window.prompt('Record corrective action (required):','Inspected produce; adjusted cooling setpoint; quality impact not assumed.');if(note===null)return;if(!note.trim()){notify('A corrective action is required.');return}setData(d=>({...d,alerts:d.alerts.map(a=>a.id===id?{...a,status:'Resolved',action:note.trim()}:a)}));addEvent('Alert resolved',`${id} · ${note.trim()}`);notify('Alert resolved and action recorded.')}
 function updateAlert(id:string,status:string){setData(d=>({...d,alerts:d.alerts.map(a=>a.id===id?{...a,status}:a)}));notify(`Alert ${status.toLowerCase()}.`)}
 function openQr(id:string){setSelected(id);setQr('');setModal('qr');import('qrcode').then(q=>q.toDataURL(`${window.location.origin}/freshlink?batch=${encodeURIComponent(id)}`,{width:220,margin:2,color:{dark:'#153b2c',light:'#ffffff'}})).then(setQr).catch(()=>notify('QR generation is temporarily unavailable.'));}
 function submitForm(e:FormEvent<HTMLFormElement>){e.preventDefault();setFormError('');const f=new FormData(e.currentTarget);const val=(name:string)=>String(f.get(name)||'').trim();
  if(modal==='book'){
   const batch=data.batches.find(b=>b.id===val('batch'));
   const facility=data.facilities.find(item=>item.id===val('facility'));
   if(batch&&facility&&!facilitySupports(facility,batch.crop)){
    setFormError(facility.crops.includes(batch.crop)?`${facility.name} cannot cover the configured ${batch.crop} temperature range.`:`${facility.name} does not support ${batch.crop}; choose a compatible facility.`);
    return;
   }
  }
  if(modal==='assign'){
   const batch=data.batches.find(b=>b.id===val('batch'));
   const vehicle=data.vehicles.find(v=>v.id===val('vehicle'));
   const range=batch&&cropSpecs.find(spec=>spec.crop===batch.crop)?.temp.match(/(\d+)[–-](\d+)/);
   const supported=vehicle?.temp.match(/(\d+)[–-](\d+)/);
   if(batch&&vehicle&&range&&supported&&(Number(supported[1])>Number(range[1])||Number(supported[2])<Number(range[2]))){setFormError(`${vehicle.id} cannot maintain the configured ${batch.crop} temperature range.`);return}
  }
  if(modal==='batch'){const quantity=Number(val('quantity'));if(quantity<=0){setFormError('Enter a valid quantity above zero.');return}const batch:Batch={id:`FL-${Date.now().toString().slice(-6)}`,crop:val('crop') as Batch['crop'],variety:val('variety'),fpo:val('fpo'),farm:val('farm'),harvest:val('harvest'),quantity,grade:val('grade'),location:val('farm'),destination:val('destination'),temp:cropSpecs.find(s=>s.crop===val('crop'))?.temp.match(/\d+/)?.[0]?Number(cropSpecs.find(s=>s.crop===val('crop'))!.temp.match(/\d+/)![0]):5,status:'Harvested',events:[{title:'Batch registered',time:new Date().toLocaleString('en-IN'),detail:`${number(quantity)} kg · Registered in FreshLink`}]};setData(d=>({...d,batches:[batch,...d.batches]}));setSelected(batch.id);addEvent('New produce batch registered',`${batch.id} · ${batch.crop} · ${batch.farm}`);setPage('Batches')}
  if(modal==='fpo'){const record:Fpo={name:val('name'),location:val('location'),crops:val('crops'),produce:Number(val('produce'))||0,contact:val('contact'),collection:'Scheduled'};if(!record.name||!record.location){setFormError('Name and location are required.');return}setData(d=>({...d,fpos:[record,...d.fpos]}));setPage('Farms & FPOs');notify('FPO profile added.')}
  if(modal==='facility'){const capacity=Number(val('capacity'));if(capacity<=0){setFormError('Enter a valid storage capacity.');return}const facility:Facility={id:`FC-${Date.now().toString().slice(-4)}`,name:val('name'),location:val('location'),type:val('type'),capacity,available:capacity,temp:val('temp'),crops:String(f.getAll('crops')).split(',').filter(Boolean),status:'Operational'};setData(d=>({...d,facilities:[facility,...d.facilities]}));setPage('Cold storage');notify('Facility added.')}
  if(modal==='book'){const batch=data.batches.find(b=>b.id===val('batch'));const facility=data.facilities.find(x=>x.id===val('facility'));const quantity=Number(val('quantity'));if(!batch||!facility||quantity<=0){setFormError('Select a batch, a facility and a positive quantity.');return}if(!facility.crops.includes(batch.crop)){setFormError(`${facility.name} does not support ${batch.crop}; choose a compatible facility.`);return}if(facility.available<quantity){setFormError(`Only ${number(facility.available)} kg capacity is available at this facility.`);return}setData(d=>{const booking={id:nextBookingId(d.bookings),batch:batch.id,facility:facility.name,quantity,status:'Confirmed'};return{...d,facilities:d.facilities.map(x=>x.id===facility.id?{...x,available:x.available-quantity}:x),batches:d.batches.map(b=>b.id===batch.id?{...b,status:'In Storage',facility:facility.name,location:facility.name,events:[...b.events,{title:'Cold storage booked',time:new Date().toLocaleString('en-IN'),detail:`${facility.name} · ${number(quantity)} kg`}]}:b),bookings:ensureUniqueBookings([booking,...d.bookings])}});setPage('Bookings');notify('Compatible storage booked; capacity updated.')}
  if(modal==='assign'){const batch=data.batches.find(b=>b.id===val('batch'));const vehicle=data.vehicles.find(v=>v.id===val('vehicle'));if(!batch||!vehicle||vehicle.status!=='Available'){setFormError('Select an available vehicle and a batch.');return}if(vehicle.capacity<batch.quantity){setFormError(`Vehicle capacity ${number(vehicle.capacity)} kg is below batch quantity ${number(batch.quantity)} kg.`);return}const shipment:Shipment={id:`SHP-${Date.now().toString().slice(-5)}`,batch:batch.id,route:`${batch.farm.split(',')[0]} → ${batch.destination.split(',')[0]}`,vehicle:vehicle.id,status:'In Transit',eta:'Schedule confirmation required',temp:batch.temp};setData(d=>({...d,vehicles:d.vehicles.map(v=>v.id===vehicle.id?{...v,status:'In Transit',destination:batch.destination}:v),batches:d.batches.map(b=>b.id===batch.id?{...b,status:'In Transit',vehicle:vehicle.id,events:[...b.events,{title:'Refrigerated transport assigned',time:new Date().toLocaleString('en-IN'),detail:`${vehicle.id} · ${batch.destination}`}]}:b),shipments:[shipment,...d.shipments]}));setPage('Shipments');notify('Reefer assigned; shipment created.')}
  setModal('');e.currentTarget.reset();}

 const crops=[...new Set(data.batches.map(b=>b.crop))];const alertOpen=data.alerts.filter(a=>a.status!=='Resolved').length;const closeModal=()=>{setModal('');setFormError('')};const openBooking=()=>{setBookingBatch(data.batches.find(b=>b.status!=='Delivered')?.id||data.batches[0].id);setModal('book');setFormError('')};
 const addBatch=<Button onClick={()=>setModal('batch')}><Plus size={15}/> Register batch</Button>;
 const statusOptions=['Harvested','Ready for pickup','Booked for pre-cooling','Pre-cooled','In Storage','In Transit','Delivered'];

 return <div className="freshlink-shell"><aside className={`fl-sidebar ${mobileOpen?'mobile-open':''}`}><div className="fl-brand"><span className="fl-brand-mark"><Sprout size={19}/></span><span>Fresh<span>Link</span><small>AGRICULTURE, CONNECTED</small></span></div><div className="fl-workspace"><div className="fl-workspace-icon">F</div><div><b>FreshLink Network</b><small>India · Demo workspace</small></div><ChevronRight size={14}/></div><div className="fl-nav-label">WORKSPACE</div><nav className="fl-sidenav">{nav.map(({name,icon:Icon})=><button key={name} className={`fl-nav-item ${page===name?'selected':''}`} onClick={()=>{setPage(name);setMobileOpen(false)}}><Icon size={16}/><span>{name}</span>{name==='Temperature & alerts'&&alertOpen>0&&<i>{alertOpen}</i>}</button>)}</nav><div className="fl-sidebar-bottom"><button className="fl-nav-item" onClick={reset}><RotateCcw size={15}/><span>Reset demo data</span></button><div className="fl-proto-card"><span><ShieldCheck size={15}/></span><div><b>Illustrative prototype</b><small>Records and sensor readings are simulated</small></div></div><div className="fl-user"><span className="fl-avatar">AN</span><span><b>Ananya Nair</b><small>Network coordinator</small></span><ChevronRight size={14}/></div></div></aside>
 <main className="fl-main"><header className="fl-topbar"><button className="fl-mobile-menu" onClick={()=>setMobileOpen(v=>!v)}><Menu size={19}/></button><div className="fl-crumb">FreshLink <ChevronRight size={13}/><b>{page}</b></div><div className="fl-top-actions"><label className="fl-search"><Search size={15}/><input placeholder="Search batches, FPOs…" value={query} onChange={e=>setQuery(e.target.value)}/><kbd>⌘ K</kbd></label><span className="fl-date"><CloudSun size={15}/> Nov 5, 2026</span><button className="fl-bell" onClick={()=>{setPage('Temperature & alerts')}} aria-label="View alerts"><Bell size={17}/>{alertOpen>0&&<i/>}</button><button className="fl-avatar top">AN</button></div></header><div className="fl-content"><div className="fl-demo-strip"><span className="fl-strip-icon"><Activity size={15}/></span><div><b>Prototype · all data is illustrative</b><span>Demo records, sensor readings and modeled impact; not measured outcomes or live tracking.</span></div><button onClick={reset}><RotateCcw size={13}/> Reset</button></div>
 {page==='Overview'&&<><Title title="Farm to market, with freshness intact." subtitle="Coordinate harvest, cooling, storage and refrigerated delivery in one place." action={<><Button kind="ghost" onClick={()=>setPage('Traceability')}><QrCode size={14}/> Batch passport</Button><Button onClick={nextDemo}><Activity size={15}/>{data.step?`Continue demo · ${data.step}/8`:'Run FreshLink demo'}</Button></>}/><div className="fl-kpi-grid"><Metric label="Produce batches" value={number(data.batches.length===20?186:data.batches.length+166)} change="12.8%" icon={<Package size={18}/>} foot="vs. previous period"/><Metric label="Active shipments" value={String(data.shipments.filter(s=>s.status==='In Transit').length+38)} change="8.2%" icon={<Truck size={18}/>} tone="blue" foot="across demo lanes"/><Metric label="Produce managed" value="245 t" change="6.4%" icon={<Sprout size={18}/>} tone="lime" foot="illustrative quantity"/><Metric label="Cold-chain facilities" value={String(data.facilities.length+16)} change="4 facilities" icon={<Snowflake size={18}/>} tone="purple" foot="in partner network"/><Metric label="Available capacity" value="380 t" change="68% occupied" icon={<Package size={18}/>} tone="amber" foot="sample network capacity"/><Metric label="Active reefers" value={String(data.vehicles.filter(v=>v.status==='In Transit').length+31)} change="6 in transit" icon={<Truck size={18}/>} tone="blue" foot="demo fleet"/><Metric label="Temperature alerts" value={String(alertOpen+3)} change={alertOpen?`${alertOpen} require action`:'All monitored'} icon={<Thermometer size={18}/>} tone="rose" foot="simulated conditions"/><Metric label="Estimated loss avoided" value="12.5 t" change="Modeled estimate" icon={<Leaf size={18}/>} tone="lime" foot="not a measured outcome"/></div>
 <div className="fl-chart-grid"><Panel title="Produce by commodity" sub="Illustrative managed volume · tonnes"><div className="fl-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={barData} margin={{left:-18,right:5,top:8,bottom:0}}><CartesianGrid vertical={false} stroke="#edf0f3"/><XAxis dataKey="name" tick={{fontSize:10,fill:'#77877f'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize:10,fill:'#98a39d'}} axisLine={false} tickLine={false}/><Tooltip/><Bar dataKey="tonnes" name="Tonnes" fill="#419670" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></Panel><Panel title="Post-harvest loss trend" sub="Hypothetical illustration · percent"><div className="fl-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={lossData} margin={{left:-15,right:8,top:8,bottom:0}}><CartesianGrid vertical={false} stroke="#edf0f3"/><XAxis dataKey="month" tick={{fontSize:10,fill:'#77877f'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize:10,fill:'#98a39d'}} axisLine={false} tickLine={false}/><Tooltip formatter={(v)=>`${v}%`}/><Legend wrapperStyle={{fontSize:10}}/><Line type="monotone" dataKey="baseline" name="Baseline (illustrative)" stroke="#c3a37a" strokeWidth={2}/><Line type="monotone" dataKey="assisted" name="Assisted scenario" stroke="#439774" strokeWidth={2}/></LineChart></ResponsiveContainer></div></Panel></div>
 <div className="fl-lower-grid"><Panel title="Recent activity" action={<button className="fl-text-link" onClick={()=>setPage('Batches')}>All activity <ArrowRight size={13}/></button>}><div className="fl-activity-list">{data.events.slice(0,5).map((e,i)=><div className="fl-activity" key={`${e.title}-${e.time}-${i}`}><span className={`fl-activity-icon ac-${i%4}`}>{i===0?<Package size={14}/>:i===1?<Snowflake size={14}/>:i===2?<CheckCircle2 size={14}/>:i===3?<Truck size={14}/>:<AlertTriangle size={14}/>}</span><span><b>{e.title}</b><small>{e.detail}</small></span><time>{e.time}</time></div>)}</div></Panel><Panel title="FreshLink demo journey" sub="8 tonnes of tomatoes · Kolar → Bengaluru"><div className="fl-step-list">{['Register 8-tonne tomato batch','Schedule FPO pickup','Book compatible packhouse slot','Record grading & pre-cooling','Assign refrigerated transport','Simulate temperature excursion','Resolve with corrective action','Complete delivery & passport'].map((s,i)=><button key={s} className={data.step>i?'done':data.step===i?'current':''} onClick={()=>{if(data.step===i)nextDemo();else if(data.step>i)notify('This demonstration step is already complete. Continue to the next step.')}}><span>{data.step>i?<Check size={12}/>:i+1}</span>{s}<ChevronRight size={13}/></button>)}</div><Button onClick={nextDemo}><ArrowRight size={14}/>{data.step>=8?'Journey complete · reset to replay':data.step?'Continue next step':'Start guided demo'}</Button></Panel></div></>}

 {page==='Batches'&&<><Title title="Produce batches" subtitle="Register, search and manage crop-specific handling from harvest through delivery." action={addBatch}/><div className="fl-filterbar"><label className="fl-search"><Search size={14}/><input value={query} placeholder="Search batch, crop, FPO…" onChange={e=>setQuery(e.target.value)}/></label><select value={cropFilter} onChange={e=>setCropFilter(e.target.value)}><option>All commodities</option>{crops.map(c=><option key={c}>{c}</option>)}</select><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option>All statuses</option>{statusOptions.map(s=><option key={s}>{s}</option>)}</select><span className="fl-result-count">{visibleBatches.length} batches</span></div><Panel title="Batch register" sub="Crop-specific temperature targets · dates and locations are sample records"><div className="fl-table-wrap"><table><thead><tr><th>Batch / crop</th><th>Farmer / FPO</th><th>Origin / destination</th><th>Harvested</th><th>Quantity</th><th>Temp · target</th><th>Status</th><th>Actions</th></tr></thead><tbody>{visibleBatches.map(b=><tr key={b.id}><td><button className="fl-batch-link" onClick={()=>{setSelected(b.id);setModal('detail')}}><b>{b.id}</b><small>{b.crop} · {b.variety}</small></button></td><td>{b.fpo}</td><td><span className="fl-route-cell">{b.farm.split(',')[0]} → {b.destination.split(',')[0]}</span><small>{b.location}</small></td><td>{b.harvest}</td><td>{number(b.quantity)} kg</td><td>{b.temp}°C <small>· {cropSpecs.find(s=>s.crop===b.crop)?.temp}</small></td><td><Badge>{b.status}</Badge></td><td><div className="fl-row-actions"><button title="View batch journey" onClick={()=>{setSelected(b.id);setModal('detail')}}><ChevronRight size={15}/></button><button title="Batch QR passport" onClick={()=>openQr(b.id)}><QrCode size={15}/></button></div></td></tr>)}</tbody></table>{visibleBatches.length===0&&<Empty text="No batches match these filters."/>}</div></Panel></>}

 {page==='Farms & FPOs'&&<><Title title="Farms & FPOs" subtitle="Agricultural partners, crop availability and first-mile collection coordination." action={<Button onClick={()=>setModal('fpo')}><Plus size={14}/> Add FPO</Button>}/><div className="fl-summary-row"><Metric label="Farm partners" value={String(data.fpos.length)} change="8 active clusters" icon={<Sprout size={18}/>} foot="sample FPO records"/><Metric label="Expected harvest" value="138 t" change="Next 7 days" icon={<Clock3 size={18}/>} tone="blue" foot="illustrative schedule"/><Metric label="Collection scheduled" value="6 clusters" change="Across 5 states" icon={<Truck size={18}/>} tone="lime" foot="demo dispatch plan"/></div><Panel title="FPO directory" sub="Search and filter agricultural collection partners"><div className="fl-filterbar"><label className="fl-search"><Search size={14}/><input value={query} placeholder="Search FPO or location…" onChange={e=>setQuery(e.target.value)}/></label><select onChange={e=>setCropFilter(e.target.value)} value={cropFilter}><option>All commodities</option>{crops.map(c=><option key={c}>{c}</option>)}</select><span className="fl-result-count">{data.fpos.filter(f=>`${f.name} ${f.location} ${f.crops}`.toLowerCase().includes(query.toLowerCase())&&(cropFilter==='All commodities'||f.crops.includes(cropFilter))).length} partners</span></div><div className="fl-table-wrap"><table><thead><tr><th>Organization</th><th>Location</th><th>Commodities</th><th>Available produce</th><th>Collection status</th><th>Contact</th><th>Registered batches</th></tr></thead><tbody>{data.fpos.filter(f=>`${f.name} ${f.location} ${f.crops}`.toLowerCase().includes(query.toLowerCase())&&(cropFilter==='All commodities'||f.crops.includes(cropFilter))).map(f=><tr key={f.name}><td><span className="fl-org"><span>{f.name.charAt(0)}</span><b>{f.name}</b></span></td><td>{f.location}</td><td>{f.crops}</td><td>{number(f.produce)} kg</td><td><Badge>{f.collection}</Badge></td><td>{f.contact}</td><td>{data.batches.filter(b=>b.fpo===f.name).length}</td></tr>)}</tbody></table></div></Panel></>}

 {page==='Cold storage'&&<><Title title="Cold storage & packhouses" subtitle="Discover compatible cooling and storage capacity; reserve capacity against a produce batch." action={<><Button kind="ghost" onClick={()=>setModal('book')}><ClipboardList size={14}/> Book storage</Button><Button onClick={()=>setModal('facility')}><Plus size={14}/> Add facility</Button></>}/><div className="fl-summary-row"><Metric label="Partner facilities" value={String(data.facilities.length)} change="Across 8 districts" icon={<Snowflake size={18}/>} foot="sample infrastructure"/><Metric label="Total network capacity" value={`${Math.round(data.facilities.reduce((a,f)=>a+f.capacity,0)/1000)} t`} change="Illustrative capacity" icon={<Package size={18}/>} tone="blue" foot="tonnes"/><Metric label="Utilization" value="68%" change="Sample occupancy" icon={<BarChart3 size={18}/>} tone="lime" foot="varies by facility"/></div><Panel title="Capacity utilization by facility" sub="Availability and commodity compatibility shown for each site"><div className="fl-capacity-list">{data.facilities.map(f=><div className="fl-capacity" key={f.id}><div className="fl-capacity-title"><span><b>{f.name}</b><small><MapPin size={12}/>{f.location} · {f.type}</small></span><Badge>{f.status}</Badge></div><div className="fl-progress"><i style={{width:`${Math.round(100*(f.capacity-f.available)/f.capacity)}%`}}/></div><div className="fl-capacity-foot"><span>{number(f.capacity-f.available)} / {number(f.capacity)} kg occupied</span><b>{number(f.available)} kg available</b></div><div className="fl-chips">{f.crops.map(c=><span key={c}>{c}</span>)}<span>{f.temp}</span><button onClick={()=>{setModal('book');setFormError('')}}>Reserve compatible capacity <ArrowRight size={12}/></button></div></div>)}</div></Panel></>}

 {page==='Refrigerated transport'&&<><Title title="Refrigerated transport" subtitle="Capacity, temperature bands and vehicle assignment for crop-compatible shipments." action={<Button onClick={()=>setModal('assign')}><Truck size={14}/> Assign vehicle</Button>}/><div className="fl-summary-row"><Metric label="Vehicles in network" value={String(data.vehicles.length)} change="15 demo records" icon={<Truck size={18}/>} foot="sample fleet"/><Metric label="Available now" value={String(data.vehicles.filter(v=>v.status==='Available').length)} change="Capacity checked" icon={<CheckCircle2 size={18}/>} tone="lime" foot="demo availability"/><Metric label="In transit" value={String(data.vehicles.filter(v=>v.status==='In Transit').length)} change="Temperature-monitored" icon={<Activity size={18}/>} tone="blue" foot="simulated locations"/></div><Panel title="Reefer fleet" sub="Vehicle availability and nominal carrying capacity"><div className="fl-filterbar"><label className="fl-search"><Search size={14}/><input placeholder="Search vehicle, transporter, location…" value={query} onChange={e=>setQuery(e.target.value)}/></label><span className="fl-result-count">{data.vehicles.filter(v=>`${v.id} ${v.operator} ${v.location}`.toLowerCase().includes(query.toLowerCase())).length} vehicles</span></div><div className="fl-table-wrap"><table><thead><tr><th>Vehicle / transporter</th><th>Capacity</th><th>Current location</th><th>Temperature band</th><th>Current shipment</th><th>Destination / ETA</th><th>Status</th></tr></thead><tbody>{data.vehicles.filter(v=>`${v.id} ${v.operator} ${v.location}`.toLowerCase().includes(query.toLowerCase())).map(v=><tr key={v.id}><td><b>{v.id}</b><small>{v.operator}</small></td><td>{number(v.capacity)} kg</td><td>{v.location}</td><td>{v.temp}</td><td>{data.shipments.find(s=>s.vehicle===v.id)?.id||'—'}</td><td>{v.destination}</td><td><Badge>{v.status}</Badge></td></tr>)}</tbody></table></div></Panel><p className="fl-note"><Truck size={14}/> Fleet status and locations are illustrative demo records, not live GPS data.</p></>}

 {page==='Temperature & alerts'&&<><Title title="Temperature monitoring & alerts" subtitle="Simulate readings against crop-specific configured ranges; an excursion is not proof of spoilage." action={<><Button kind="ghost" onClick={()=>simulateTemp(-2)}><ArrowDownRight size={14}/> Simulate cooling</Button><Button kind="danger" onClick={()=>simulateTemp(4)}><ArrowUpRight size={14}/> Simulate warming</Button></>}/><div className="fl-monitor-grid"><Panel title="Simulated sensor readings" sub="Select a batch to view crop-specific target and change its demo reading"><label className="fl-field">Monitored batch<select value={selected} onChange={e=>setSelected(e.target.value)}>{data.batches.map(b=><option key={b.id} value={b.id}>{b.id} · {b.crop} · {b.location}</option>)}</select></label>{selectedBatch&&<><div className="fl-temperature-read"><span className="fl-temp-icon"><Thermometer size={20}/></span><div><small>{selectedBatch.crop} · configured demo range {cropSpecs.find(s=>s.crop===selectedBatch.crop)?.temp}</small><strong>{selectedBatch.temp}°<i>C</i></strong><Badge>{(()=>{const spec=cropSpecs.find(s=>s.crop===selectedBatch.crop)!.temp.match(/(\d+)–(\d+)/)!;return selectedBatch.temp>Number(spec[2])?'Warning':selectedBatch.temp<Number(spec[1])?'Warning':'Normal'})()}</Badge></div><button className={`fl-toggle ${sensor?'on':''}`} onClick={()=>setSensor(v=>!v)}>{sensor?'Sensor simulation on':'Start live simulation'}</button></div><div className="fl-telemetry"><span>Relative humidity<strong>{cropSpecs.find(s=>s.crop===selectedBatch.crop)?.humidity}</strong></span><span>Sensor update<strong>{sensor?'Simulated · just now':'Manual demo reading'}</strong></span><span>Current location<strong>{selectedBatch.location}</strong></span></div><p className="fl-note"><AlertTriangle size={14}/> A threshold breach triggers inspection and documented corrective action. It does not establish that produce is spoiled.</p></>}</Panel><Panel title="Temperature alerts" sub={`${alertOpen} open · original readings remain in the action history`}>{data.alerts.length===0?<Empty text="No sensor alerts. Run the simulation to create an illustrative reading."/>:<div className="fl-alert-list">{data.alerts.map(a=><article className={`fl-alert ${a.status==='Resolved'?'resolved':''}`} key={a.id}><span className={`fl-severity ${a.severity.toLowerCase()}`}>{a.severity==='Critical'?<AlertTriangle size={15}/>:<Thermometer size={15}/>}</span><div className="fl-alert-body"><div><b>{a.id} · {a.batch}</b><Badge>{a.status}</Badge></div><p>{a.temp}°C · {a.location}</p><small>Owner: {a.owner} · Action: {a.action}</small>{a.status!=='Resolved'&&<div className="fl-row-actions"><button onClick={()=>updateAlert(a.id,'Acknowledged')}>Acknowledge</button><button onClick={()=>resolveAlert(a.id)}>Resolve with action</button></div>}</div></article>)}</div>}</Panel></div><Panel title="Crop-specific handling references" sub="Illustrative operating ranges only—confirm protocols with qualified post-harvest specialists"><div className="fl-crop-specs">{cropSpecs.map(c=><div key={c.crop}><b>{c.crop}</b><span>{c.temp}</span><small>{c.humidity} RH</small></div>)}</div></Panel></>}

 {page==='Shipments'&&<><Title title="Shipments & route visibility" subtitle="Track sample handovers and simulated reefer status; no live location integration is connected." action={<Button onClick={()=>setModal('assign')}><Truck size={14}/> Assign vehicle</Button>}/><div className="fl-route-layout"><Panel title="Route overview" sub="Schematic routes from farm clusters to destination markets"><div className="fl-schematic-map"><div className="fl-map-grid"/><svg viewBox="0 0 600 280" role="img" aria-label="Schematic map showing sample shipment routes across India"><path d="M105 108 Q210 86 298 125 T488 173"/><path d="M165 200 Q226 149 298 125 T430 86"/><path d="M244 229 Q260 178 298 125 T330 78"/><path d="M105 108 Q175 198 244 229"/><path d="M165 200 Q300 214 488 173"/><circle cx="105" cy="108" r="6"/><circle cx="298" cy="125" r="7"/><circle cx="488" cy="173" r="6"/><circle cx="165" cy="200" r="6"/><circle cx="430" cy="86" r="5"/><circle cx="244" cy="229" r="5"/><circle cx="330" cy="78" r="5"/><text x="76" y="93">Nashik</text><text x="265" y="109">Hyderabad</text><text x="455" y="162">Vijayawada</text><text x="135" y="222">Mumbai</text><text x="407" y="72">Bengaluru</text><text x="222" y="252">Madurai</text><text x="307" y="63">Kolar</text></svg><span className="fl-map-caption"><MapPin size={13}/> Sample corridor map · not a GPS feed</span></div></Panel><Panel title="Shipment status" sub={`${data.shipments.length} demo consignments`}>{data.shipments.map(s=><div className="fl-shipment-card" key={s.id}><span className="fl-shipment-icon"><Truck size={17}/></span><div><b>{s.id} · {s.batch}</b><small>{s.route} · {s.vehicle}</small><small>{s.temp}°C simulated · ETA {s.eta}</small></div><Badge>{s.status}</Badge><button onClick={()=>{setSelected(s.batch);setPage('Traceability')}} aria-label="View shipment batch passport"><ChevronRight size={15}/></button></div>)}</Panel></div></>}

 {page==='Traceability'&&<><Title title="Batch passport & traceability" subtitle="A QR-linked digital history of recorded events. Entries may be simulated or manually entered." action={<Button onClick={()=>openQr(selected)}><QrCode size={14}/> Generate QR passport</Button>}/><div className="fl-trace-grid"><Panel title="Select batch" sub="Open its event history and generate a QR-linked digital identity"><label className="fl-field">Produce batch<select value={selected} onChange={e=>setSelected(e.target.value)}>{data.batches.map(b=><option key={b.id} value={b.id}>{b.id} · {b.crop} · {b.fpo}</option>)}</select></label>{selectedBatch&&<div className="fl-passport"><div className="fl-passport-header"><span className="fl-passport-leaf"><Sprout size={19}/></span><span><small>DIGITAL BATCH PASSPORT</small><b>{selectedBatch.id}</b></span><Badge>{selectedBatch.status}</Badge></div><div className="fl-passport-crop">{selectedBatch.crop}<small>{selectedBatch.variety} · {selectedBatch.grade}</small></div><div className="fl-passport-facts"><span>Farmer / FPO<b>{selectedBatch.fpo}</b></span><span>Farm origin<b>{selectedBatch.farm}</b></span><span>Harvest date<b>{selectedBatch.harvest}</b></span><span>Harvest quantity<b>{number(selectedBatch.quantity)} kg</b></span><span>Handling target<b>{cropSpecs.find(s=>s.crop===selectedBatch.crop)?.temp}</b></span><span>Current condition<b>{selectedBatch.temp}°C · {selectedBatch.location}</b></span><span>Destination buyer<b>{selectedBatch.destination}</b></span><span>Reefer transport<b>{selectedBatch.vehicle||'Not yet assigned'}</b></span></div><div className="fl-passport-note"><ShieldCheck size={14}/> Digital event record · simulated, entered and externally verified records are not independently certified in this prototype.</div><Button kind="soft" onClick={()=>openQr(selectedBatch.id)}><QrCode size={15}/> View QR code</Button></div>}</Panel><Panel title="Batch journey timeline" sub={`${selectedBatch?.events.length||0} recorded events · newest events shown in order`}><div className="fl-timeline">{selectedBatch?.events.map((e,i)=><article key={`${e.title}-${e.time}-${i}`}><span className="fl-timeline-dot">{i===0?<Sprout size={12}/>:i===selectedBatch.events.length-1?<CheckCircle2 size={12}/>:<Activity size={12}/>}</span><div><b>{e.title}</b><small>{e.detail}</small><time>{e.time}</time><Badge>{i===0?'Manual / demo':'Simulated record'}</Badge></div></article>)}</div></Panel></div></>}

 {page==='Analytics'&&<><Title title="Analytics & performance" subtitle="Track operational measures; sample metrics and modeled outcomes are hypothetical, not pilot results." action={<Button kind="ghost" onClick={()=>{const text='metric,value,note\nProduce handled,245 tonnes,illustrative sample\nPost-harvest loss baseline,12.6%,hypothetical\nAssisted handling scenario,8.9%,hypothetical\nTemperature excursion rate,6.4%,demo records\nSuccessful delivery rate,94%,illustrative';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv'}));a.download='freshlink-demo-analytics.csv';a.click();notify('Demo analytics CSV exported.')}}><Download size={14}/> Export CSV</Button>}/><div className="fl-kpi-grid"><Metric label="Produce handled" value="245 t" change="Illustrative sample" icon={<Sprout size={18}/>} foot="not a validated result"/><Metric label="Saleable quantity" value="219 t" change="Modeled estimate" icon={<CheckCircle2 size={18}/>} tone="lime" foot="actual quality may vary"/><Metric label="First cooling" value="4.2 hrs" change="Hypothetical median" icon={<Clock3 size={18}/>} tone="blue" foot="harvest to cooling"/><Metric label="Temperature excursions" value="6.4%" change="Demo sensor data" icon={<Thermometer size={18}/>} tone="rose" foot="not real sensor readings"/><Metric label="Storage utilization" value="68%" change="Sample capacity" icon={<Snowflake size={18}/>} tone="blue" foot="network-wide illustration"/><Metric label="Reefer utilization" value="72%" change="Demo fleet records" icon={<Truck size={18}/>} foot="tonne-km unavailable"/><Metric label="Quality rejection" value="3.8%" change="Hypothetical" icon={<AlertTriangle size={18}/>} tone="amber" foot="not a measured outcome"/><Metric label="Average cost / tonne" value={money(2840)} change="Sample booking costs" icon={<Activity size={18}/>} tone="purple" foot="operational cost unverified"/></div><div className="fl-chart-grid"><Panel title="Commodity volume" sub="Illustrative production sample · tonnes"><div className="fl-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={barData}><CartesianGrid vertical={false} stroke="#edf0f3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><Tooltip/><Bar dataKey="tonnes" fill="#439774" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div></Panel><Panel title="Baseline vs. assisted handling" sub="Hypothetical modeled loss rates · not measured outcomes"><div className="fl-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={lossData}><CartesianGrid vertical={false} stroke="#edf0f3"/><XAxis dataKey="month" tick={{fontSize:10}}/><YAxis unit="%" tick={{fontSize:10}}/><Tooltip formatter={(v)=>`${v}%`}/><Legend/><Area dataKey="baseline" name="Illustrative baseline" stroke="#c5a57c" fill="#f5eee4"/><Area dataKey="assisted" name="Hypothetical assisted" stroke="#439774" fill="#e5f1e9"/></AreaChart></ResponsiveContainer></div></Panel></div></>}

 {page==='Bookings'&&<><Title title="Bookings & transactions" subtitle="Facility reservations, batches and capacity changes in the demonstration." action={<Button onClick={()=>setModal('book')}><Plus size={14}/> Book storage</Button>}/><Panel title="Operational bookings" sub="Demo reservation records · no real payments or external orders"><div className="fl-table-wrap"><table><thead><tr><th>Booking</th><th>Batch</th><th>Farm partner</th><th>Cold-chain facility</th><th>Quantity</th><th>Booking date</th><th>Destination</th><th>Status</th></tr></thead><tbody>{data.bookings.map((b,i)=><tr key={`${b.id}-${i}`}><td><b>{b.id}</b></td><td>{b.batch}</td><td>{data.batches.find(x=>x.id===b.batch)?.fpo||'Kolar Fresh Farmers FPO'}</td><td>{b.facility}</td><td>{number(b.quantity)} kg</td><td>Nov 5, 2026</td><td>{data.batches.find(x=>x.id===b.batch)?.destination||'Bengaluru, Karnataka'}</td><td><Badge>{b.status}</Badge></td></tr>)}</tbody></table></div></Panel></>}

 {page==='Settings'&&<><Title title="Settings & handling protocols" subtitle="Demo company profile, crop-specific operating references and notification preferences."/><div className="fl-settings-grid"><Panel title="Company profile" sub="Current browser-only demo workspace"><form className="fl-settings-form" onSubmit={e=>{e.preventDefault();notify('Company profile settings saved.')}}><label className="fl-field">Organization name<input value={settings.company} onChange={e=>setSettings({...settings,company:e.target.value})}/></label><label className="fl-field">Preferred crop coverage<select value={settings.crop} onChange={e=>setSettings({...settings,crop:e.target.value})}><option>All compatible crops</option>{cropSpecs.map(s=><option key={s.crop}>{s.crop}</option>)}</select></label><Button><Check size={14}/> Save preferences</Button></form></Panel><Panel title="Notification preferences" sub="Simulated app-level notification settings"><div className="fl-pref"><span><b>Temperature exceptions</b><small>Notify the assigned operator when a demo reading exceeds its crop range.</small></span><button className={`fl-switch ${settings.alerts?'on':''}`} onClick={()=>setSettings({...settings,alerts:!settings.alerts})}/></div><div className="fl-pref"><span><b>Daily operations digest</b><small>Summarize collection, storage and delivery activity.</small></span><button className={`fl-switch ${settings.digest?'on':''}`} onClick={()=>setSettings({...settings,digest:!settings.digest})}/></div></Panel><Panel title="Crop handling references" sub="Sample defaults only; confirm locally validated commodity protocols before operations."><div className="fl-spec-table">{cropSpecs.map(s=><div key={s.crop}><b>{s.crop}</b><span>Temperature: {s.temp}</span><span>Relative humidity: {s.humidity}</span></div>)}</div></Panel><Panel title="Demo workspace data" sub="Reset the local browser prototype to its original bundled sample records."><p className="fl-reset-copy">Reset will clear FreshLink changes saved by this browser and restore the original illustrative datasets. It does not affect FreightLoop.</p><Button kind="danger" onClick={reset}><RotateCcw size={14}/> Reset FreshLink demo data</Button></Panel></div></>}
 </div></main>

 {modal==='batch'&&<div className="fl-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeModal()}}><div className="fl-modal"><div className="fl-modal-head"><span><b>Register produce batch</b><small>Create a new traceable agricultural batch.</small></span><button onClick={closeModal}><X size={18}/></button></div><form onSubmit={submitForm}><div className="fl-form-grid"><label className="fl-field">Commodity<select name="crop">{cropSpecs.map(c=><option key={c.crop}>{c.crop}</option>)}</select></label><label className="fl-field">Crop variety<input name="variety" placeholder="e.g. Arka Rakshak" required/></label><label className="fl-field">Farmer / FPO<select name="fpo">{data.fpos.map(f=><option key={f.name}>{f.name}</option>)}</select></label><label className="fl-field">Farm location<select name="farm">{['Kolar, Karnataka','Chikkaballapur, Karnataka','Nashik, Maharashtra','Pune, Maharashtra','Vijayawada, Andhra Pradesh','Madurai, Tamil Nadu'].map(x=><option key={x}>{x}</option>)}</select></label><label className="fl-field">Harvest date<input type="date" name="harvest" defaultValue="2026-11-05" required/></label><label className="fl-field">Quantity (kg)<input type="number" name="quantity" min="1" placeholder="8000" required/></label><label className="fl-field">Quality grade<select name="grade"><option>Grade A</option><option>Grade B</option><option>Grade C</option></select></label><label className="fl-field">Buyer destination<select name="destination"><option>Bengaluru, Karnataka</option><option>Mumbai, Maharashtra</option><option>Hyderabad, Telangana</option><option>Chennai, Tamil Nadu</option></select></label></div>{formError&&<p className="fl-form-error">{formError}</p>}<div className="fl-modal-actions"><Button kind="ghost" onClick={closeModal}>Cancel</Button><Button><Plus size={14}/> Register batch</Button></div></form></div></div>}

 {modal==='fpo'&&<div className="fl-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeModal()}}><div className="fl-modal"><div className="fl-modal-head"><span><b>Add FPO / farm partner</b><small>Register an agricultural collection partner.</small></span><button onClick={closeModal}><X size={18}/></button></div><form onSubmit={submitForm}><div className="fl-form-grid"><label className="fl-field">Organization name<input name="name" placeholder="e.g. Kolar Fresh Farmers FPO" required/></label><label className="fl-field">Location<input name="location" placeholder="District, state" required/></label><label className="fl-field">Commodity focus<input name="crops" placeholder="Tomatoes, Grapes" required/></label><label className="fl-field">Available produce (kg)<input name="produce" type="number" min="0" defaultValue="0"/></label><label className="fl-field">Contact number<input name="contact" placeholder="+91 …"/></label></div>{formError&&<p className="fl-form-error">{formError}</p>}<div className="fl-modal-actions"><Button kind="ghost" onClick={closeModal}>Cancel</Button><Button><Plus size={14}/> Add partner</Button></div></form></div></div>}

 {modal==='facility'&&<div className="fl-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeModal()}}><div className="fl-modal"><div className="fl-modal-head"><span><b>Add cold-chain facility</b><small>Set available capacity and supported commodities.</small></span><button onClick={closeModal}><X size={18}/></button></div><form onSubmit={submitForm}><div className="fl-form-grid"><label className="fl-field">Facility name<input name="name" required placeholder="Facility name"/></label><label className="fl-field">Location<input name="location" required placeholder="District, state"/></label><label className="fl-field">Facility type<select name="type"><option>Pre-cooling centre</option><option>Packhouse</option><option>Cold storage</option><option>Multi-commodity store</option><option>Ripening chamber</option><option>Processing facility</option></select></label><label className="fl-field">Total storage capacity (kg)<input name="capacity" type="number" min="1" required placeholder="10000"/></label><label className="fl-field">Temperature range<input name="temp" defaultValue="2–10°C" required/></label><fieldset className="fl-checkbox-field"><legend>Supported commodities</legend>{cropSpecs.map(s=><label key={s.crop}><input type="checkbox" name="crops" value={s.crop} defaultChecked={s.crop==='Tomatoes'}/>{s.crop}</label>)}</fieldset></div>{formError&&<p className="fl-form-error">{formError}</p>}<div className="fl-modal-actions"><Button kind="ghost" onClick={closeModal}>Cancel</Button><Button><Plus size={14}/> Add facility</Button></div></form></div></div>}

 {modal==='book'&&<div className="fl-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeModal()}}><div className="fl-modal"><div className="fl-modal-head"><span><b>Book compatible cold storage</b><small>Commodity support and available kilograms are validated.</small></span><button onClick={closeModal}><X size={18}/></button></div><form onSubmit={submitForm}><div className="fl-form-grid"><label className="fl-field span-2">Produce batch<select name="batch" required defaultValue=""><option value="" disabled>Select batch…</option>{data.batches.map(b=><option key={b.id} value={b.id}>{b.id} · {b.crop} · {number(b.quantity)} kg · {b.fpo}</option>)}</select></label><label className="fl-field span-2">Facility<select name="facility" required defaultValue=""><option value="" disabled>Select a facility…</option>{data.facilities.map(f=><option key={f.id} value={f.id}>{f.name} · {f.crops.join(', ')} · {number(f.available)} kg available</option>)}</select></label><label className="fl-field span-2">Capacity to reserve (kg)<input name="quantity" type="number" required min="1" placeholder="Enter booking quantity"/></label></div>{formError&&<p className="fl-form-error">{formError}</p>}<div className="fl-modal-actions"><Button kind="ghost" onClick={closeModal}>Cancel</Button><Button><CheckCircle2 size={14}/> Confirm booking</Button></div></form></div></div>}

 {modal==='assign'&&<div className="fl-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeModal()}}><div className="fl-modal"><div className="fl-modal-head"><span><b>Assign refrigerated transport</b><small>Vehicle capacity is checked against batch quantity.</small></span><button onClick={closeModal}><X size={18}/></button></div><form onSubmit={submitForm}><div className="fl-form-grid"><label className="fl-field span-2">Produce batch<select name="batch" required>{data.batches.map(b=><option key={b.id} value={b.id}>{b.id} · {b.crop} · {number(b.quantity)} kg</option>)}</select></label><label className="fl-field span-2">Available refrigerated vehicle<select name="vehicle" required>{data.vehicles.filter(v=>v.status==='Available').map(v=><option key={v.id} value={v.id}>{v.id} · {v.operator} · {number(v.capacity)} kg · {v.temp}</option>)}</select></label><p className="fl-form-hint span-2">This prototype validates nominal capacity and records a shipment. Live route, reefer sensor compatibility and GPS require verified partner data.</p></div>{formError&&<p className="fl-form-error">{formError}</p>}<div className="fl-modal-actions"><Button kind="ghost" onClick={closeModal}>Cancel</Button><Button><Truck size={14}/> Assign vehicle</Button></div></form></div></div>}

 {modal==='detail'&&selectedBatch&&<div className="fl-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeModal()}}><div className="fl-modal"><div className="fl-modal-head"><span><b>{selectedBatch.id} · {selectedBatch.crop}</b><small>{selectedBatch.fpo} · {number(selectedBatch.quantity)} kg</small></span><button onClick={closeModal}><X size={18}/></button></div><div className="fl-detail-grid"><span>Variety<b>{selectedBatch.variety} · {selectedBatch.grade}</b></span><span>Farm / origin<b>{selectedBatch.farm}</b></span><span>Harvest date<b>{selectedBatch.harvest}</b></span><span>Current status<b><Badge>{selectedBatch.status}</Badge></b></span><span>Current temperature<b>{selectedBatch.temp}°C · target {cropSpecs.find(s=>s.crop===selectedBatch.crop)?.temp}</b></span><span>Assigned facility<b>{selectedBatch.facility||'Not assigned'}</b></span><span>Buyer destination<b>{selectedBatch.destination}</b></span><span>Trip status<b>{selectedBatch.vehicle||'Transport not assigned'}</b></span></div><label className="fl-field">Update batch status<select value={selectedBatch.status} onChange={e=>{const status=e.target.value;setData(d=>({...d,batches:d.batches.map(b=>b.id===selectedBatch.id?{...b,status,events:[...b.events,{title:'Batch status updated',time:new Date().toLocaleString('en-IN'),detail:`${selectedBatch.status} → ${status}`}]}:b)}));notify(`Batch status updated to ${status}.`)}}>{statusOptions.map(s=><option key={s}>{s}</option>)}</select></label><div className="fl-modal-actions"><Button kind="ghost" onClick={()=>openQr(selectedBatch.id)}><QrCode size={14}/> QR passport</Button><Button kind="ghost" onClick={closeModal}>Close</Button></div></div></div>}

 {modal==='qr'&&selectedBatch&&<div className="fl-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeModal()}}><div className="fl-modal qr-modal"><div className="fl-modal-head"><span><b>Digital batch passport</b><small>{selectedBatch.id} · {selectedBatch.crop} · {selectedBatch.fpo}</small></span><button onClick={closeModal}><X size={18}/></button></div><div className="fl-qr-content">{qr?<img src={qr} alt={`QR code for batch ${selectedBatch.id}`}/>:<div className="fl-qr-loading"><QrCode size={30}/><span>Generating QR code…</span></div>}<strong>{selectedBatch.id}</strong><span>{selectedBatch.crop} · {number(selectedBatch.quantity)} kg</span><p>Scans open this batch’s FreshLink demonstration record on this app’s /freshlink route. Other users need access to the running application.</p></div><div className="fl-modal-actions"><Button kind="ghost" onClick={closeModal}>Close</Button><Button onClick={()=>{navigator.clipboard?.writeText(`${window.location.origin}/freshlink?batch=${selectedBatch.id}`);notify('Batch passport link copied.')}}>Copy passport link</Button></div></div></div>}

 {toast&&<div className="fl-toast"><CheckCircle2 size={16}/>{toast}<button onClick={()=>setToast('')}><X size={14}/></button></div>}</div>
}
